#!/usr/bin/env bash
set -euo pipefail

# ============================================================================
# USDC Compliance Integration - Dependency Setup
# Generated by GL1 Compliance Wizard
# ============================================================================

echo "🔧 Setting up USDC Compliance Integration..."

# 1. Initialize git if not already
if [ ! -d ".git" ]; then
  echo "📁 Initializing git repository..."
  git init && git add -A && git commit -m "Initial commit"
fi

# 2. Install Forge dependencies
echo "📦 Installing forge-std..."
forge install foundry-rs/forge-std

echo "📦 Installing OpenZeppelin Contracts..."
forge install OpenZeppelin/openzeppelin-contracts

echo "📦 Installing OpenZeppelin Contracts Upgradeable..."
forge install OpenZeppelin/openzeppelin-contracts-upgradeable

# Note: CHAINLINK_CCI policy-management package is pre-included in lib/chainlink-ccid/
# No forge install needed for it.

echo ""
echo "✅ Setup complete!"
echo ""
echo "Next steps:"
echo "  forge build    # Compile contracts"
echo "  forge test     # Run tests"
